using NUnit.Framework;
using System.Linq;

[TestFixture]
public class SecondLargestTests
{
    [Test]
    public void Returns_Second_Largest_Distinct_Number()
    {
        var result = SecondLargest(new[] { 5, 1, 5, 3, 4 });
        Assert.That(result, Is.EqualTo(4));
    }

    private int? SecondLargest(int[] nums)
    {
        var distinct = nums.Distinct().OrderBy(x => x).ToArray();

        if (distinct.Length < 2)
            return null;

        return distinct[^2];
    }
}
